window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cf8632c079947f06"]={"versions": [{"id": "FIG-cf8632c079947f06", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm des AUTOSAR ECU-Configuration-Metamodells (ECUC Parameter Definition Metamodel, M2-Ebene).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Referenz-Parameter (<code>ConfigReference</code>) innerhalb von BSW-Modul-Konfigurationsbeschreibungen (<code><em>.bmd</code> / <code></em>.armdl</code>).</li>\n<li><strong>Architektur-Einordnung:</strong> Ermöglicht die typisierte Verknüpfung von Konfigurations-Containern (<code>ParamConfContainerDef</code>) untereinander sowie die typisierte Referenzierung externer Artefakte (System Description, SWC-Templates) zur automatisierten Codegenerierung des BSW-Stacks, der RTE und der EcuC-Strukturen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>ConfigReference</code></strong> <em>(abstrakt, Stereotyp: <code>«atpIdentifiable»</code>)</em>: Basisklasse aller Konfigurationsreferenzen im Paket <code>CommonConfigurationAttributes</code>. Erbt identifizierbare Eigenschaften (u. a. <code>shortName</code>, <code>uuid</code>).</li>\n<li><strong><code>ParamConfContainerDef</code></strong> <em>(Paket: <code>ContainerDef</code>)</em>: Repräsentiert Container-Definitionen für BSW-Parameter.</li>\n<li>Attribut: <code>+ multipleConfigurationContainer: Boolean</code> (definiert, ob der Container in Multi-Configuration-Sets / Post-Build variieren darf).</li>\n<li><strong><code>ReferenceDef</code></strong>: Spezifikation einer direkten 1:1-Referenz auf eine definierte Container-Klasse.</li>\n<li><strong><code>SymbolicNameReferenceDef</code></strong>: Spezialisierung von <code>ReferenceDef</code> zur Erzeugung symbolischer Identifier/Handles (z. B. Com-Signal-IDs, PduR-Routing-Path-IDs, CanIf-TxPdu-IDs).</li>\n<li><strong><code>ChoiceReferenceDef</code></strong>: Polymorphe Referenzdefinition, die zur Entwurfszeit eine Auswahl aus verschiedenen Ziel-Container-Typen erlaubt.</li>\n<li><strong><code>InstanceReferenceDef</code></strong>: Definiert Referenzen auf Instanzen innerhalb hierarchischer Strukturen (z. B. Port-/Signal-Instanzen in verschachtelten Software-Component-Prototypen).</li>\n<li>Attribute: <code>+ destinationContext: String</code> (Metaklasse des Hierarchie-Kontexts), <code>+ destinationType: String</code> (Metaklasse des Ziel-Elements).</li>\n<li><strong><code>ForeignReferenceDef</code></strong>: Definiert Referenzen außerhalb der EcuC-Parameterhierarchie in das AUTOSAR-Systemmodell (z. B. Referenz auf ein <code>SystemSignal</code>, <code>ISignal</code> oder <code>CanCluster</code> der Systembeschreibung).</li>\n<li>Attribut: <code>+ destinationType: String</code> (vollqualifizierter Metaklassenname des ARXML-Zieltyps).</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>Komposition:</strong> <code>ParamConfContainerDef</code> $\\blacklozenge\\xrightarrow{\\text{+reference}\\ [0..*]}$ <code>ConfigReference</code></li>\n</ul>\n<p class=\"fig-p\">Ein Konfigurations-Container besitzt null bis viele Referenzdefinitionen; die Lebensdauer der Referenzdefinition ist an den Container gebunden.</p>\n<ul class=\"fig-list\">\n<li><strong>Generalisierungen (Vererbung):</strong></li>\n<li><code>ChoiceReferenceDef</code> $\\xrightarrow{\\triangle}$ <code>ConfigReference</code></li>\n<li><code>ReferenceDef</code> $\\xrightarrow{\\triangle}$ <code>ConfigReference</code></li>\n<li><code>InstanceReferenceDef</code> $\\xrightarrow{\\triangle}$ <code>ConfigReference</code></li>\n<li><code>ForeignReferenceDef</code> $\\xrightarrow{\\triangle}$ <code>ConfigReference</code></li>\n<li><code>SymbolicNameReferenceDef</code> $\\xrightarrow{\\triangle}$ <code>ReferenceDef</code></li>\n<li><strong>Assoziationen (Zielbeziehungen):</strong></li>\n<li><code>ReferenceDef</code> $\\xrightarrow{\\text{+destination}\\ [1]}$ <code>ParamConfContainerDef</code>: Erfordert exakt eine spezifische Ziel-Container-Definition.</li>\n<li><code>ChoiceReferenceDef</code> $\\xrightarrow{\\text{+destination}\\ [*]}$ <code>ParamConfContainerDef</code>: Erlaubt die Zuweisung beliebiger Ziel-Container-Definitionen aus einer Menge definierter Alternativen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Eigenschaft:</strong> Als statisches M2-Metamodell existiert kein direktes Laufzeitverhalten (keine Runtime-Calls, Zustandsübergänge oder Callbacks).</li>\n<li><strong>Generierungs-/Auflösungsablauf (M1-zu-M0-Transformation):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>EcuC-Instanziierung:</em> Werkzeuge (EcuExtract/EcuC-Editor) instanziieren gemäß den Regeln von <code>ConfigReference</code> konkrete <code>ConfigReferenceValue</code>-Elemente.</li>\n<li><em>Konsistenzprüfung:</em> Validierung, ob Zielreferenzen (<code>destinationType</code>, <code>destinationContext</code>, <code>destination 1</code>) in der ARXML existieren und typkompatibel sind.</li>\n<li><em>BSW-Generierung (M0/C-Code):</em> BSW-Code-Generatoren lösen die modellierten Referenzen auf:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SymbolicNameReferenceDef</code> $\\rightarrow$ Generierung von Präprozessor-Makros / C-Enums (z. B. <code>#define PduRConf_PduRSrcPdu_Can_Engine 0U</code>).</li>\n<li><code>ReferenceDef</code> $\\rightarrow$ Generierung von Zeiger-Arrays, Tabellenindizes oder Struct-Initialisierern (z. B. Zeiger auf die referenzierte <code>CanIfInitHohConfig</code>).</li>\n<li><code>ForeignReferenceDef</code> $\\rightarrow$ Verknüpfung von BSW-Objekten mit System-Signalen/Frames.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW- & Treiber-Entwicklung:</strong></li>\n<li>Referenzen steuern die Generierung von Indizes und C-Strukturen (<code>Post-Build</code>- bzw. <code>Link-Time</code>-Konfigurationen). Zirkuläre oder unvollständig aufgelöste <code>ReferenceDef</code>-Ketten führen zu Build-Fehlern bei der Codegenerierung.</li>\n<li><code>SymbolicNameReferenceDef</code> erzwingt in Modulen die Bereitstellung konsistenter Identifikatoren gemäß AUTOSAR-Namenskonventionen (<code>&lt;Module&gt;_&lt;ParameterShortName&gt;</code>), über die Treiber- und Stack-APIs parametrisiert werden (z. B. <code>CanIf_Transmit(CanIfTxSduId, ...)</code>).</li>\n<li><strong>Applikations- & RTE-Integration:</strong></li>\n<li><code>InstanceReferenceDef</code> ist essenziell für die RTE-Generierung, um softwareseitige Datenports über Modulgrenzen hinweg eindeutig spezifischen Kontexten zuzuordnen.</li>\n<li><code>ForeignReferenceDef</code> bindet Konfigurationswerte direkt an Kommunikationsmatrizen (DBC/FIBEX/ARXML-Systembeschreibungen); Änderungen an der Cluster-/Signalbeschreibung erfordern eine Re-Generierung der betroffenen BSW-Module.</li>\n</ul>"}, {"id": "FIG-c47712107c06b9f4", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm des AUTOSAR ECU-Configuration-Metamodells (ECUC Parameter Definition Metamodel, M2-Ebene).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Referenz-Parameter (<code>ConfigReference</code>) innerhalb von BSW-Modul-Konfigurationsbeschreibungen (<code><em>.bmd</code> / <code></em>.armdl</code>).</li>\n<li><strong>Architektur-Einordnung:</strong> Ermöglicht die typisierte Verknüpfung von Konfigurations-Containern (<code>ParamConfContainerDef</code>) untereinander sowie die typisierte Referenzierung externer Artefakte (System Description, SWC-Templates) zur automatisierten Codegenerierung des BSW-Stacks, der RTE und der EcuC-Strukturen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>ConfigReference</code></strong> <em>(abstrakt)</em>: Basisklasse aller Konfigurationsreferenzen im Paket <code>CommonConfigurationAttributes</code>.</li>\n<li><strong><code>ParamConfContainerDef</code></strong> <em>(Paket: <code>ContainerDef</code>)</em>: Repräsentiert Container-Definitionen für BSW-Parameter.</li>\n<li>Attribut: <code>+ multipleConfigurationContainer: Boolean</code> (definiert, ob der Container in Multi-Configuration-Sets / Post-Build variieren darf).</li>\n<li><strong><code>ReferenceParamDef</code></strong>: Spezifikation einer direkten 1:1-Referenz auf eine definierte Container-Klasse.</li>\n<li><strong><code>SymbolicNameReferenceParamDef</code></strong>: Spezialisierung von <code>ReferenceParamDef</code> zur Erzeugung symbolischer Identifier/Handles (z. B. Com-Signal-IDs, PduR-Routing-Path-IDs, CanIf-TxPdu-IDs).</li>\n<li><strong><code>ChoiceReferenceParamDef</code></strong>: Polymorphe Referenzdefinition, die zur Entwurfszeit eine Auswahl aus verschiedenen Ziel-Container-Typen erlaubt.</li>\n<li><strong><code>InstanceReferenceParamDef</code></strong>: Definiert Referenzen auf Instanzen innerhalb hierarchischer Strukturen (z. B. Port-/Signal-Instanzen in verschachtelten Software-Component-Prototypen).</li>\n<li>Attribute: <code>+ destinationContext: String</code> (Metaklasse des Hierarchie-Kontexts), <code>+ destinationType: String</code> (Metaklasse des Ziel-Elements).</li>\n<li><strong><code>ForeignReferenceParamDef</code></strong>: Definiert Referenzen außerhalb der EcuC-Parameterhierarchie in das AUTOSAR-Systemmodell (z. B. Referenz auf ein <code>SystemSignal</code>, <code>ISignal</code> oder <code>CanCluster</code> der Systembeschreibung).</li>\n<li>Attribut: <code>+ destinationType: String</code> (vollqualifizierter Metaklassenname des ARXML-Zieltyps).</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>Komposition:</strong> <code>ParamConfContainerDef</code> $\\blacklozenge\\xrightarrow{\\text{+reference}\\ [0..*]}$ <code>ConfigReference</code></li>\n</ul>\n<p class=\"fig-p\">Ein Konfigurations-Container besitzt null bis viele Referenzdefinitionen; die Lebensdauer der Referenzdefinition ist an den Container gebunden.</p>\n<ul class=\"fig-list\">\n<li><strong>Generalisierungen (Vererbung):</strong></li>\n<li><code>ChoiceReferenceParamDef</code> $\\xrightarrow{\\triangle}$ <code>ConfigReference</code></li>\n<li><code>ReferenceParamDef</code> $\\xrightarrow{\\triangle}$ <code>ConfigReference</code></li>\n<li><code>InstanceReferenceParamDef</code> $\\xrightarrow{\\triangle}$ <code>ConfigReference</code></li>\n<li><code>ForeignReferenceParamDef</code> $\\xrightarrow{\\triangle}$ <code>ConfigReference</code></li>\n<li><code>SymbolicNameReferenceParamDef</code> $\\xrightarrow{\\triangle}$ <code>ReferenceParamDef</code></li>\n<li><strong>Assoziationen (Zielbeziehungen):</strong></li>\n<li><code>ReferenceParamDef</code> $\\xrightarrow{\\text{+destination}\\ [1]}$ <code>ParamConfContainerDef</code>: Erfordert exakt eine spezifische Ziel-Container-Definition.</li>\n<li><code>ChoiceReferenceParamDef</code> $\\xrightarrow{\\text{+destination}\\ [*]}$ <code>ParamConfContainerDef</code>: Erlaubt die Zuweisung beliebiger Ziel-Container-Definitionen aus einer Menge definierter Alternativen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Eigenschaft:</strong> Als statisches M2-Metamodell existiert kein direktes Laufzeitverhalten (keine Runtime-Calls, Zustandsübergänge oder Callbacks).</li>\n<li><strong>Generierungs-/Auflösungsablauf (M1-zu-M0-Transformation):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>EcuC-Instanziierung:</em> Werkzeuge (EcuExtract/EcuC-Editor) instanziieren gemäß den Regeln von <code>ConfigReference</code> konkrete <code>ConfigReferenceValue</code>-Elemente.</li>\n<li><em>Konsistenzprüfung:</em> Validierung, ob Zielreferenzen (<code>destinationType</code>, <code>destinationContext</code>, <code>destination 1</code>) in der ARXML existieren und typkompatibel sind.</li>\n<li><em>BSW-Generierung (M0/C-Code):</em> BSW-Code-Generatoren lösen die modellierten Referenzen auf:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SymbolicNameReferenceDef</code> $\\rightarrow$ Generierung von Präprozessor-Makros / C-Enums (z. B. <code>#define PduRConf_PduRSrcPdu_Can_Engine 0U</code>).</li>\n<li><code>ReferenceDef</code> $\\rightarrow$ Generierung von Zeiger-Arrays, Tabellenindizes oder Struct-Initialisierern (z. B. Zeiger auf die referenzierte <code>CanIfInitHohConfig</code>).</li>\n<li><code>ForeignReferenceDef</code> $\\rightarrow$ Verknüpfung von BSW-Objekten mit System-Signalen/Frames.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Standardisierungskonformität:</strong> Verbindliche Metamodell-Definition für Autoren von AUTOSAR-Basissoftware-Modulbeschreibungen (BSW-Lieferanten).</li>\n<li><strong>Referenzauflösung:</strong></li>\n<li>Werkzeuge müssen sicherstellen, dass bei <code>ReferenceParamDef</code> exakt ein Ziel-Container angegeben wird.</li>\n<li>Bei <code>ChoiceReferenceParamDef</code> darf das Ziel nur einem der deklarierten Zielcontainer entsprechen.</li>\n<li>Bei <code>ForeignReferenceParamDef</code> und <code>InstanceReferenceParamDef</code> steuern die String-Attribute <code>destinationType</code> bzw. <code>destinationContext</code> die Metamodell-Validierung gegen externe XML-Namensräume bzw. AUTOSAR-Modellhierarchien.</li>\n<li><strong>Implementierungshinweis:</strong> Namenskonventionen und Typbezeichner müssen strikt mit den XML-Schemadefinitionen (XSD) des jeweiligen AUTOSAR-Releases übereinstimmen.</li>\n</ul>"}, {"id": "FIG-319121664848e87b", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm des AUTOSAR ECU-Configuration-Metamodells (ECUC Parameter Definition Metamodel, M2-Ebene).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Metaklassen für Referenz-Parameter (<code>ConfigReference</code>) innerhalb von BSW-Modul-Konfigurationsbeschreibungen (<code><em>.bmd</code> / <code></em>.armdl</code>).</li>\n<li><strong>Architektur-Einordnung:</strong> Ermöglicht die typisierte Verknüpfung von Konfigurations-Containern (<code>ParamConfContainerDef</code>) untereinander sowie die typisierte Referenzierung externer Artefakte (System Description, SWC-Templates) zur automatisierten Codegenerierung des BSW-Stacks, der RTE und der EcuC-Strukturen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>ConfigReference</code></strong> <em>(abstrakt)</em>: Basisklasse aller Konfigurationsreferenzen im Paket <code>CommonConfigurationAttributes</code>.</li>\n<li><strong><code>ParamConfContainerDef</code></strong> <em>(Paket: <code>ContainerDef</code>)</em>: Repräsentiert Container-Definitionen für BSW-Parameter.</li>\n<li>Attribut: <code>+ multipleConfigurationContainer: Boolean</code> (definiert, ob der Container in Multi-Configuration-Sets / Post-Build variieren darf).</li>\n<li><strong><code>ReferenceParamDef</code></strong>: Spezifikation einer direkten 1:1-Referenz auf eine definierte Container-Klasse.</li>\n<li><strong><code>SymbolicNameReferenceParamDef</code></strong>: Spezialisierung von <code>ReferenceParamDef</code> zur Erzeugung symbolischer Identifier/Handles (z. B. Com-Signal-IDs, PduR-Routing-Path-IDs, CanIf-TxPdu-IDs).</li>\n<li><strong><code>ChoiceReferenceParamDef</code></strong>: Polymorphe Referenzdefinition, die zur Entwurfszeit eine Auswahl aus verschiedenen Ziel-Container-Typen erlaubt.</li>\n<li><strong><code>InstanceReferenceParamDef</code></strong>: Definiert Referenzen auf Instanzen innerhalb hierarchischer Strukturen (z. B. Port-/Signal-Instanzen in verschachtelten Software-Component-Prototypen).</li>\n<li>Attribute: <code>+ destinationContext: String</code> (Metaklasse des Hierarchie-Kontexts), <code>+ destinationType: String</code> (Metaklasse des Ziel-Elements).</li>\n<li><strong><code>ForeignReferenceParamDef</code></strong>: Definiert Referenzen außerhalb der EcuC-Parameterhierarchie in das AUTOSAR-Systemmodell (z. B. Referenz auf ein <code>SystemSignal</code>, <code>ISignal</code> oder <code>CanCluster</code> der Systembeschreibung).</li>\n<li>Attribut: <code>+ destinationType: String</code> (vollqualifizierter Metaklassenname des ARXML-Zieltyps).</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>Komposition:</strong> <code>ParamConfContainerDef</code> $\\blacklozenge\\xrightarrow{\\text{+reference}\\ [0..*]}$ <code>ConfigReference</code></li>\n</ul>\n<p class=\"fig-p\">Ein Konfigurations-Container besitzt null bis viele Referenzdefinitionen; die Lebensdauer der Referenzdefinition ist an den Container gebunden.</p>\n<ul class=\"fig-list\">\n<li><strong>Generalisierungen (Vererbung):</strong></li>\n<li><code>ChoiceReferenceParamDef</code> $\\xrightarrow{\\triangle}$ <code>ConfigReference</code></li>\n<li><code>ReferenceParamDef</code> $\\xrightarrow{\\triangle}$ <code>ConfigReference</code></li>\n<li><code>InstanceReferenceParamDef</code> $\\xrightarrow{\\triangle}$ <code>ConfigReference</code></li>\n<li><code>ForeignReferenceParamDef</code> $\\xrightarrow{\\triangle}$ <code>ConfigReference</code></li>\n<li><code>SymbolicNameReferenceParamDef</code> $\\xrightarrow{\\triangle}$ <code>ReferenceParamDef</code></li>\n<li><strong>Assoziationen (Zielbeziehungen):</strong></li>\n<li><code>ReferenceParamDef</code> $\\xrightarrow{\\text{+destination}\\ [1]}$ <code>ParamConfContainerDef</code>: Erfordert exakt eine spezifische Ziel-Container-Definition.</li>\n<li><code>ChoiceReferenceParamDef</code> $\\xrightarrow{\\text{+destination}\\ [*]}$ <code>ParamConfContainerDef</code>: Erlaubt die Zuweisung beliebiger Ziel-Container-Definitionen aus einer Menge definierter Alternativen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Eigenschaft:</strong> Als statisches M2-Metamodell existiert kein direktes Laufzeitverhalten (keine Runtime-Calls, Zustandsübergänge oder Callbacks).</li>\n<li><strong>Generierungs-/Auflösungsablauf (M1-zu-M0-Transformation):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>EcuC-Instanziierung:</em> Werkzeuge (EcuExtract/EcuC-Editor) instanziieren gemäß den Regeln von <code>ConfigReference</code> konkrete <code>ConfigReferenceValue</code>-Elemente.</li>\n<li><em>Konsistenzprüfung:</em> Validierung, ob Zielreferenzen (<code>destinationType</code>, <code>destinationContext</code>, <code>destination 1</code>) in der ARXML existieren und typkompatibel sind.</li>\n<li><em>BSW-Generierung (M0/C-Code):</em> BSW-Code-Generatoren lösen die modellierten Referenzen auf:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SymbolicNameReferenceDef</code> $\\rightarrow$ Generierung von Präprozessor-Makros / C-Enums (z. B. <code>#define PduRConf_PduRSrcPdu_Can_Engine 0U</code>).</li>\n<li><code>ReferenceDef</code> $\\rightarrow$ Generierung von Zeiger-Arrays, Tabellenindizes oder Struct-Initialisierern (z. B. Zeiger auf die referenzierte <code>CanIfInitHohConfig</code>).</li>\n<li><code>ForeignReferenceDef</code> $\\rightarrow$ Verknüpfung von BSW-Objekten mit System-Signalen/Frames.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Standardisierungskonformität:</strong> Verbindliche Metamodell-Definition für Autoren von AUTOSAR-Basissoftware-Modulbeschreibungen (BSW-Lieferanten).</li>\n<li><strong>Referenzauflösung:</strong></li>\n<li>Werkzeuge müssen sicherstellen, dass bei <code>ReferenceParamDef</code> exakt ein Ziel-Container angegeben wird.</li>\n<li>Bei <code>ChoiceReferenceParamDef</code> darf das Ziel nur einem der deklarierten Zielcontainer entsprechen.</li>\n<li>Bei <code>ForeignReferenceParamDef</code> und <code>InstanceReferenceParamDef</code> steuern die String-Attribute <code>destinationType</code> bzw. <code>destinationContext</code> die Metamodell-Validierung gegen externe XML-Namensräume bzw. AUTOSAR-Modellhierarchien.</li>\n<li><strong>Implementierungshinweis:</strong> Namenskonventionen und Typbezeichner müssen strikt mit den XML-Schemadefinitionen (XSD) des jeweiligen AUTOSAR-Releases übereinstimmen.</li>\n</ul>"}], "trans": [{"from": "FIG-cf8632c079947f06", "to": "FIG-c47712107c06b9f4", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Stereotyp <code>«atpIdentifiable»</code> an Klasse <code>ConfigReference</code> entfernt.</li>\n<li>Klasse <code>ChoiceReferenceDef</code> umbenannt in <code>ChoiceReferenceParamDef</code>.</li>\n<li>Klasse <code>ReferenceDef</code> umbenannt in <code>ReferenceParamDef</code>.</li>\n<li>Klasse <code>SymbolicNameReferenceDef</code> umbenannt in <code>SymbolicNameReferenceParamDef</code>.</li>\n<li>Klasse <code>InstanceReferenceDef</code> umbenannt in <code>InstanceReferenceParamDef</code>.</li>\n<li>Klasse <code>ForeignReferenceDef</code> umbenannt in <code>ForeignReferenceParamDef</code>.</li>\n</ul>"}, {"from": "FIG-c47712107c06b9f4", "to": "FIG-319121664848e87b", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
